style.css:
@-moz-document domain("music.youtube.com"), url-prefix("https://music.youtube.com/") {
/*
Made by Lotos 

I did lots of changes here so base is not mine
*/

 /* animation of opening / closening player */

ytmusic-app-layout > [slot=player-page] {
    transition: transform 3s cubic-bezier(0.6, 0, 0.3, 1);
}


/* visibility of content */
#content {
    visibility: visible !important;
}
#content ytmusic-browse-response {
    display: block !important;
}

/* background */
#player-page {
    background: url("https://i.imgur.com/FFetlNK.gif") !important;
  background-size: cover !important;
  background-repeat: no-repeat !important;
  background-attachment: fixed !important;
}

.background-gradient {
	background: url("https://i.imgur.com/FFetlNK.gif") !important;
  background-attachment: fixed !important;
  background-repeat: no-repeat !important;
}

#player-page,.content {
	background:transparent !important;
}

#mini-guide-background,#guide,#scrim,#contentContainer,#guide-wrapper,#guide-content,#guide-renderer,#guide-renderer > #sections  {
	background:transparent !important;
}

/* navigation bar */
#nav-bar-background,.search-box,#suggestion-list {
    background: transparent !important
}
#nav-bar-divider {
	display: none;
}

/* Panel of player */
#player-bar-background {
    backdrop-filter: blur(10px) brightness(0.5);
    opacity: 0.5;
}
ytmusic-player-bar {
    background: transparent;
}

/* Cover (picture) */
yt-img-shadow[object-fit=COVER] img.yt-img-shadow {
	border-radius: 25px;
  backdrop-filter: blur(10px) brightness(0.5);
    background: transparent !important;
}
ytmusic-player {
	background: #00000050 !important;
}

/* Cover (Video) */
.song-media-controls.ytmusic-player {
	border-radius: 25px;
}
.html5-video-player:not(.ytp-transparent) {
	border-radius: 25px;
}

/* Sounds */
ytmusic-player-queue-item {
	transition: .1s linear;
	border-radius: 15px;
}

/* Slider of progress */
#primaryProgress {
    transition: 1s linear;
    background:#4605ad !important;
}
#sliderKnob {
    transition: 0.5s linear;
}

/* All buttons */
tp-yt-paper-icon-button {
    transition: .2s linear;
  opacity: 0.5;
}



/* Youtube music logo*/
.ytmusic-nav-bar .logo {  
  content: url("https://i.imgur.com/AQ1d6Dh.png") !important;
  position: relative !important;
  left: 15px;
}
}
